'use strict';
const KEY='daymark-concept-v1';
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(n,d=0)=>Number(n||0).toLocaleString('uk-UA',{maximumFractionDigits:d});
const round=n=>Math.round(n*10)/10;
const today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Kyiv',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const dt=s=>new Date(s+'T12:00:00Z');
const key=d=>d.toISOString().slice(0,10);
function offset(s,n){const d=dt(s);d.setUTCDate(d.getUTCDate()+n);return key(d);}
function months(s,n){const d=dt(s),day=d.getUTCDate();d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+n);const last=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate();d.setUTCDate(Math.min(day,last));return key(d);}
const diff=(a,b)=>Math.round((dt(b)-dt(a))/86400000);
const fdate=(s,long=false)=>new Intl.DateTimeFormat('uk-UA',{day:'numeric',month:long?'long':'short',timeZone:'UTC'}).format(dt(s));
const uid=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=crypto.getRandomValues(new Uint8Array(1))[0]&15;return(c==='x'?r:(r&3)|8).toString(16);});
const I={recipes:'<path d="M4 3h7c2 0 3 1 3 3v15c0-2-2-3-4-3H4V3Zm10 3c0-2 2-3 4-3h3v15h-3c-2 0-4 1-4 3M7 7h3m-3 4h3"/>',basket:'<path d="M3 8h18l-2 13H5L3 8Zm4 0 5-6 5 6M9 12v5m6-5v5"/>',today:'<rect x="3" y="4" width="18" height="17" rx="4"/><path d="M7 2v5m10-5v5M3 10h18m-13 5 3 3 5-6"/>',journey:'<path d="M4 19h16M5 16l5-5 4 2 5-9M15 4h4v4"/>',food:'<path d="M5 3v7m3-7v7m-6-7v7c0 2 6 2 6 0M5 12v9m13 0V3c-5 2-5 10 0 10"/>',move:'<path d="m5 4 3 2-4 6m16 8-3-2 4-6M8 7l8 10M3 5l4-3m14 17-4 3m-6-12 3-3"/>',sleep:'<path d="M20.5 14A8.5 8.5 0 0 1 10 3.5 9 9 0 1 0 20.5 14Z"/><path d="m17 3 .5 2 2 .5-2 .5-.5 2-.5-2-2-.5 2-.5Z"/>',profile:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',camera:'<path d="m8 5 2-2h4l2 2h4a2 2 0 0 1 2 2v12H2V7a2 2 0 0 1 2-2Z"/><circle cx="12" cy="12" r="4"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',barcode:'<path d="M3 3h4M3 3v4m18-4h-4m4 0v4M3 21h4m-4 0v-4m18 4h-4m4 0v-4M7 7v10m3-10v10m4-10v10m3-10v10"/>',spaces:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',plus:'<path d="M12 4v16M4 12h16"/>',water:'<path d="M12 2S5 10 5 15a7 7 0 0 0 14 0c0-5-7-13-7-13Z"/>',arrow:'<path d="M5 19 19 5M5 5h14v14"/>'};
const icon=n=>'<svg viewBox="0 0 24 24" aria-hidden="true">'+(I[n]||I.arrow)+'</svg>';
const VIEW_NAMES={supports:'Мої опори',coach:'Помічник дня',recipes:'Що приготувати?',today:'Мій день',journey:'Мій шлях',food:'Харчування',move:'Рух',sleep:'Сон',profile:'Мій простір',goals:'Мої цілі'};
const TYPE_NAMES={breakfast:'Сніданок',lunch:'Обід',dinner:'Вечеря',snack:'Перекуси',drink:'Напої'};
const HABITS=Object.fromEntries(Object.entries(SUPPORT_DEFINITIONS).map(([id,x])=>[id,[x.name,x.sub]]));
const GOAL_KINDS=Object.fromEntries(Object.entries(GOAL_TEMPLATES).map(([id,x])=>[id,x.name]));
const DB=FOOD_CATALOG;
function makeDemo(){const t=today(),s=offset(t,-18),checks={};for(let i=0;i<18;i++)if(![3,8,14].includes(i))checks[offset(s,i)]=i===11?'minimum':'full';const logs={};for(let i=6;i>=0;i--)logs[offset(t,-i)]={habits:{food:true,move:i%3!==0,sleep:true},water:i===0?4:6,steps:i===0?6410:4200+(6-i)*540,workouts:[],sleep:{bed:'23:30',wake:['07:15','07:00','06:45','07:30','07:10','07:20','07:15'][i],quality:'okay'},meals:[]};logs[t].meals=[{id:uid(),name:'Вівсянка, банан, йогурт',type:'breakfast',grams:320,kcal:385,p:15,f:10,c:59,source:'demo',emoji:'🥣'},{id:uid(),name:'Боул із куркою та рисом',type:'lunch',grams:380,kcal:520,p:39,f:18,c:50,source:'demo',emoji:'🥗'},{id:uid(),name:'Капучино з молоком',type:'drink',grams:200,kcal:94,p:5.4,f:4.5,c:8.5,source:'demo',emoji:'☕'}];return{version:1,demo:true,profile:{name:'Алекс',age:'',height:'',weight:'',targetWeight:''},settings:{calories:2100,steps:8000,sleep:8,style:'balanced',fasting:false,motion:true},goals:[{id:'main',title:'Сильніша версія себе',kind:'form',start:s,end:months(s,4),habits:['food','move','sleep'],minimum:'10 хвилин прогулянки й один запис їжі',checks},{id:'sleep-goal',title:'Мій вечірній ритм',kind:'sleep',start:offset(t,-6),end:offset(t,21),habits:['sleep'],minimum:'Відкласти телефон перед сном',checks:{[offset(t,-1)]:'full',[offset(t,-3)]:'full',[offset(t,-5)]:'minimum'}}],active:'main',logs,favorites:[],fastingStart:null};}
let state=makeDemo(),storageOK=true;
try{const raw=localStorage.getItem(KEY);if(raw){const data=JSON.parse(raw);if(data.version===1&&Array.isArray(data.goals)&&data.goals.length&&data.logs&&data.profile&&data.settings)state=validateState(data);}}catch{storageOK=false;}
let currentView='today',selectedDate=today(),foodFilter='all',monthView=key(new Date(Date.UTC(dt(today()).getUTCFullYear(),dt(today()).getUTCMonth(),1))).slice(0,7),modalData={},onboard=null;
const goal=()=>state.goals.find(g=>g.id===state.active)||state.goals[0];
const total=g=>diff(g.start,g.end)+1;
const completed=g=>Object.entries(g.checks).filter(([d,v])=>d>=g.start&&d<=g.end&&d<=today()&&v).length;
const elapsed=g=>Math.max(0,Math.min(total(g),diff(g.start,today())+1));
function log(d=selectedDate){return state.logs[d]||(state.logs[d]={habits:{},water:0,steps:0,workouts:[],meals:[],sleep:null});}
function totals(d=selectedDate){const meals=state.logs[d]?.meals||[];return meals.reduce((a,m)=>{if(m.kcal===null||m.kcal===undefined)a.missing++;else a.kcal+=m.kcal;for(const n of ['p','f','c'])a[n]+=Number(m[n]||0);return a;},{kcal:0,p:0,f:0,c:0,missing:0});}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;return true;}catch{storageOK=false;toast('Браузер не зберіг зміни. Завантаж копію в «Моєму просторі».');return false;}}
function toast(s){$('toast').textContent=s;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),3300);}
function navHTML(bottom=false){const items=bottom?[['today','Сьогодні'],['journey','Мій шлях'],['food','Їжа'],['recipes','Ідеї їжі'],['profile','Я']]:[['today','Мій день'],['journey','Мій шлях'],['food','Харчування'],['recipes','Що приготувати?'],['move','Рух'],['sleep','Сон'],['profile','Мій простір']];return items.map(([v,name])=>'<button class="nav-item '+(currentView===v?'active':'')+'" '+(v==='spaces'?'data-action="spaces"':'data-view="'+v+'"')+'>'+icon(v)+'<span>'+name+'</span>'+(v==='journey'?'<span class="nav-count">'+state.goals.length+'</span>':'')+'</button>').join('');}
function dateControl(){return '<div class="date-control"><button data-action="date-prev" aria-label="Попередній день">‹</button><span>'+fdate(selectedDate)+'</span><button data-action="date-next" aria-label="Наступний день" '+(selectedDate>=today()?'disabled':'')+'>›</button></div>';}
function pageTop(title,sub='',action=''){return '<div class="page-top"><div><div class="eyebrow"><i class="status-dot"></i>'+esc(sub||'DAYMARK / ТВІЙ ОСОБИСТИЙ РИТМ')+'</div><h1>'+title+'</h1></div>'+action+'</div>';}
function ringPanel(){return energyPanel();}
function spark(color){return '<svg class="spark-line" viewBox="0 0 90 38" aria-hidden="true"><path d="M2 31 13 21 24 26 36 11 48 16 61 6 73 14 87 3" fill="none" stroke="'+color+'" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg>';}
function sleepDuration(s){if(!s?.bed||!s.wake)return 0;const to=v=>Number(v.split(':')[0])*60+Number(v.split(':')[1]);return ((to(s.wake)-to(s.bed)+1440)%1440)/60;}
function hoursText(n){const mins=Math.round(n*60);return Math.floor(mins/60)+' год '+String(mins%60).padStart(2,'0')+' хв';}
function spacesDeck(){const l=log(),t=totals(),h=sleepDuration(l.sleep);return '<div class="spaces-head"><h2>Мої простори</h2><button class="text-btn" data-action="spaces">Усі екрани '+icon('spaces')+'</button></div><div class="space-deck">'+[['food','Харчування',num(t.kcal)+' ккал','їжа з увагою','#81452c'],['move','Рух',num(l.steps)+'','кроків у своєму темпі','#50711c'],['sleep','Сон',h?hoursText(h):'Мій ритм','час на відновлення','#6b59af']].map(([v,title,value,sub,color])=>'<button class="space-card '+v+'" data-view="'+v+'"><span class="space-card-top">'+title+'<span class="space-icon">'+icon(v)+'</span></span><strong>'+value+'</strong><small>'+sub+'</small>'+spark(color)+'</button>').join('')+'</div>';}
function monthCalendar(g,ym,compact=false){return victoryCalendar(g,ym,false);}
function monthTitle(ym){return new Intl.DateTimeFormat('uk-UA',{month:'long',year:'numeric',timeZone:'UTC'}).format(dt(ym+'-01'));}
function calendarKey(){return '<div class="calendar-key"><span><i></i>День для себе</span><span><i class="minimum"></i>Мій мінімум</span><span><i class="future"></i>Попереду</span></div>';}
function calendarPanel(){return '<section class="panel calendar-panel"><div class="panel-head"><h2 style="text-transform:capitalize">'+monthTitle(monthView)+'</h2><div class="date-control"><button data-action="month-prev" aria-label="Попередній місяць">‹</button><button data-action="month-next" aria-label="Наступний місяць">›</button></div></div>'+monthCalendar(goal(),monthView,true)+calendarKey()+'</section>';}
function habitPanel(){return smartHabitPanel();}

function todayView(){return homeApp();}
function goalCard(g){const p=completed(g)/total(g)*100;return '<section class="goal-card '+(g.id===state.active?'primary-goal':'')+'"><div class="goal-meta"><span>'+esc(GOAL_KINDS[g.kind]||'Моя ціль')+'</span><span>'+ (g.id===state.active?'АКТИВНА':'')+'</span></div><h2>'+esc(g.title)+'</h2><p>'+fdate(g.start)+' — '+fdate(g.end)+' · '+total(g)+' днів</p><div class="progress-track"><div style="width:'+p+'%"></div></div><div class="goal-meta"><span>'+completed(g)+' днів відзначено</span><button class="text-btn" style="color:inherit" data-action="choose-goal" data-id="'+g.id+'">Відкрити шлях ↗</button></div></section>';}
function goalsView(){return pageTop('Твоя наступна версія.','ВЕЛИКІ ТА МАЛЕНЬКІ ЦІЛІ','<button class="btn blue" data-action="new-goal">＋ Нова ціль</button>')+'<div class="goals-grid">'+state.goals.map(goalCard).join('')+'</div><div class="insight-card"><h2>Одна дата.<br>Багато маленьких кроків.</h2><p>Підготовка до дня народження, повернення до спорту, сон або власна звичка. Кожна ціль має свій календар і твій власний мінімум.</p></div>';}
function journeyView(){const g=goal(),n=completed(g),e=elapsed(g),p=e?Math.round(n/e*100):0;let calendars='',cursor=g.start.slice(0,7),end=g.end.slice(0,7),limit=0;while(cursor<=end&&limit++<25){calendars+='<section class="panel"><h3 style="text-transform:capitalize">'+monthTitle(cursor)+'</h3>'+monthCalendar(g,cursor)+'</section>';cursor=months(cursor+'-01',1).slice(0,7);}return pageTop('Кожен день — позначка.','МІЙ ШЛЯХ / '+esc(g.title),'<button class="btn ghost small-btn" data-view="goals">Усі цілі ↗</button>')+'<div class="journey-mode"><span>Мій календар</span><button data-view="coach">✦ Аналіз дня й тижня ↗</button></div><div class="journey-metrics"><div class="metric-card"><span>Днів для себе</span><b>'+n+'</b><span>із '+total(g)+' у твоєму шляху</span></div><div class="metric-card"><span>Мій ритм</span><b>'+p+'<small style="font-size:16px">%</small></b><span>із днів, що вже минули</span></div><div class="metric-card"><span>До своєї дати</span><b>'+Math.max(0,diff(today(),g.end))+'</b><span>днів попереду</span></div></div><div class="panel" style="margin-bottom:20px"><div class="panel-head"><div><h2>'+esc(g.title)+'</h2><p class="small muted">'+fdate(g.start,true)+' — '+fdate(g.end,true)+'</p></div><button class="btn blue small-btn" data-action="share">Поділитися ↗</button></div><div class="progress-track" style="background:#e9ece2"><div style="width:'+(n/total(g)*100)+'%;background:var(--blue)"></div></div>'+calendarKey()+'</div><div class="journey-full">'+calendars+'</div>';}
function mealRows(){const meals=(state.logs[selectedDate]?.meals||[]).filter(m=>foodFilter==='all'||m.type===foodFilter);let h='';for(const[type,name]of Object.entries(TYPE_NAMES)){const group=meals.filter(m=>m.type===type);if(!group.length)continue;h+='<section class="meal-section"><div class="meal-section-head"><h3>'+name+'</h3><span>'+num(group.reduce((a,m)=>a+(m.kcal||0),0))+' ккал</span></div>'+group.map(m=>'<button class="food-row" data-action="edit-meal" data-id="'+m.id+'"><span class="food-visual">'+(m.photo?'<img src="'+m.photo+'" alt="" style="width:100%;height:100%;object-fit:cover;border-radius:13px">':esc(m.emoji||'◌'))+'</span><span><h4>'+esc(m.name)+'</h4><p>'+num(m.grams)+' '+(m.unit==='ml'?'мл':'г')+' · '+(m.source==='demo'?'демо-запис':m.source==='photo-demo'?'демо-оцінка':m.source==='label'?'за етикеткою':m.source==='restaurant'?'дані закладу':m.source==='reference'?'довідник':m.source==='calculated'?'за складом':m.source==='user-food'?'мій продукт':'внесено вручну')+'</p></span><span class="food-cal">'+(m.kcal===null?'—':num(m.kcal))+'<small>ккал '+(m.source==='photo-demo'?'≈':'')+'</small></span></button>').join('')+'</section>';}return h||'<div class="empty">Тут починається твій щоденник.<br>Додай їжу, каву чи перекус.</div>';}
function foodView(){const t=totals(),l=log();return pageTop('Їжа. Без зайвого шуму.','ХАРЧУВАННЯ / '+(state.settings.style==='keto'?'МІЙ ОРІЄНТИР ВУГЛЕВОДІВ':state.settings.style==='flexible'?'ГНУЧКИЙ РЕЖИМ':'У МОЄМУ РИТМІ'),dateControl())+coachTeaser()+'<div class="catalog-fast diary-fast"><button data-action="search">🍔 Їжа й заклади</button><button data-action="drink-builder">☕ Мій напій</button></div><button class="recipe-diary-link" data-view="recipes"><span>✳ Не знаєш, що поїсти?</span><strong>100 ідей під твій настрій ↗</strong></button><div class="tool-grid"><button class="tool-card featured" data-action="photo">'+icon('camera')+'<strong>Фото тарілки</strong><span>Сценарій AI-оцінки ↗</span></button><button class="tool-card" data-action="search">'+icon('search')+'<strong>Знайти продукт</strong><span>Продукти й заклади ↗</span></button><button class="tool-card" data-action="label">'+icon('barcode')+'<strong>За етикеткою</strong><span>Грами та склад ↗</span></button></div><div class="food-layout"><div><div class="pill-row" style="margin-bottom:20px">'+[['all','Усе'],['breakfast','Сніданок'],['lunch','Обід'],['dinner','Вечеря'],['snack','Перекуси'],['drink','Напої']].map(([k,n])=>'<button class="pill '+(foodFilter===k?'active':'')+'" data-action="food-filter" data-id="'+k+'">'+n+'</button>').join('')+'</div>'+mealRows()+'<button class="btn blue full" data-action="food-add">＋ Ще їжа або напій</button></div><div>'+ringPanel()+'<section class="panel bottom-space"><div class="panel-head"><h2>Моя вода</h2><span>'+num(l.water*.25,2)+' л</span></div><div class="inline-chips">'+Array.from({length:8},(_,i)=>'<button class="icon-button" style="background:'+(i<l.water?'#dbe5ff':'#f1f4ec')+';color:'+(i<l.water?'var(--blue)':'#b2b9aa')+'" data-action="water-set" data-value="'+(i+1)+'" aria-label="Позначити '+(i+1)+' склянок води">'+icon('water')+'</button>').join('')+'</div><p class="small muted">Одна позначка — 250 мл. Це щоденник, а не призначена норма.</p><button class="text-btn" data-action="water-clear">Скинути позначки</button></section>'+(state.settings.fasting?fastingCard():'')+'<p class="note bottom-space">Орієнтир калорій задаєш ти. Витрати на тренування не додаємо автоматично до «дозволеної їжі».</p></div></div>';}
function fastingCard(){const hrs=state.fastingStart?(Date.now()-state.fastingStart)/3600000:0;return '<section class="panel bottom-space"><div class="eyebrow">ДОДАТКОВИЙ РЕЖИМ</div><h2 style="margin-top:12px">Пауза між їжею</h2><p style="font-size:35px;font-weight:700">'+(state.fastingStart?hoursText(hrs):'Без таймера')+'</p><p class="small muted">Відлік часу без цілі «довше». Завершуй, коли тобі потрібно.</p><button class="btn ghost full" data-action="fasting">'+(state.fastingStart?'Завершити паузу':'Почати відлік')+'</button></section>';}
function historyBars(kind){let h='<div class="history">';for(let i=6;i>=0;i--){const d=offset(selectedDate,-i),l=state.logs[d],v=kind==='sleep'?sleepDuration(l?.sleep):l?.steps||0,max=kind==='sleep'?10:10000;h+='<div class="history-bar"><b>'+(v?(kind==='sleep'?num(v,1):num(v)):'—')+'</b><i style="height:'+Math.min(v/max*105,105)+'px;background:'+(kind==='sleep'?'var(--purple)':'var(--lime)')+'"></i><span>'+new Intl.DateTimeFormat('uk-UA',{weekday:'short',timeZone:'UTC'}).format(dt(d))+'</span></div>';}return h+'</div>';}
function sleepView(){const l=log(),duration=sleepDuration(l.sleep),sg=state.goals.find(g=>g.kind==='sleep');return pageTop('Відновлення — теж рух.','ПРОСТІР СНУ / '+fdate(selectedDate),dateControl())+coachTeaser()+'<div class="top-grid"><section class="night-hero"><div class="night-stars"></div><div><div class="eyebrow">МІЙ СОН ЦІЄЇ НОЧІ</div><h2>'+ (duration?hoursText(duration):'Свій ритм.')+'</h2><p>'+(l.sleep?esc(l.sleep.bed)+' → '+esc(l.sleep.wake)+' · внесено вручну':'Додай час сну, щоб побачити свій ритм')+'</p><div class="moon" aria-hidden="true">☾</div></div><button class="btn white" data-action="sleep-log">'+(l.sleep?'Редагувати сон':'＋ Додати сон')+'</button></section><section class="panel"><div class="panel-head"><h2>Останні 7 ночей</h2><span class="chip">години</span></div>'+historyBars('sleep')+'<p class="small muted">Показуємо тільки внесені записи. Порожній день — це відсутність даних.</p></section></div><div class="lower-grid"><section class="panel"><div class="panel-head"><h2>Мій вечірній простір</h2><span class="chip">твій вибір</span></div><button class="habit '+(l.habits.sleep?'checked':'')+'" data-action="habit" data-id="sleep"><span class="check-box">'+(l.habits.sleep?'✓':'')+'</span><span><strong>Подбав / подбала про свій сон</strong><small>Так, як це було можливо сьогодні</small></span></button><div class="insight-card"><h2>Не лише встигати.<br>Ще й відновлюватися.</h2><p>Сон має власний колір, історію й простір. Його не потрібно «заробляти» продуктивним днем.</p></div></section>'+(sg?goalCard(sg):'<section class="panel"><h2>Ціль для сну</h2><p class="section-sub">Створи окремий календар для вечірнього ритму.</p><button class="btn blue" data-action="new-goal">＋ Створити ціль</button></section>')+'</div>';}
function moveView(){const l=log();return pageTop('Рух у твоєму темпі.','ПРОСТІР РУХУ / '+fdate(selectedDate),dateControl())+'<div class="top-grid"><section class="movement-hero"><div class="eyebrow">МОЇ КРОКИ СЬОГОДНІ</div><h2>'+num(l.steps)+'</h2><p class="small">'+(state.settings.steps?'Мій орієнтир — '+num(state.settings.steps):'Власний темп без обов’язкової норми')+'</p><div class="big-arrow">↗</div><button class="btn" data-action="steps">＋ Внести кроки</button></section><section class="panel"><div class="panel-head"><h2>Мій рух за тиждень</h2><span class="chip">кроки</span></div>'+historyBars('move')+'</section></div><div class="metric-grid"><div class="metric-card"><span>Тренувань</span><b>'+l.workouts.length+'</b><span>за обраний день</span></div><div class="metric-card"><span>Час у русі</span><b>'+l.workouts.reduce((a,w)=>a+w.minutes,0)+'</b><span>хвилин внесено</span></div><button class="metric-card" style="text-align:left" data-action="integration"><span>Мої пристрої</span><b>⌚</b><span>Apple Health / Health Connect ↗</span></button></div><div class="lower-grid"><section class="panel"><div class="panel-head"><h2>Мої активності</h2><button class="text-btn" data-action="workout">＋ Додати</button></div>'+(l.workouts.length?l.workouts.map(w=>'<div class="timeline-row"><span class="timeline-icon">↗</span><span><p>'+esc(w.name)+'</p><small>Внесено вручну</small></span><span>'+w.minutes+' хв <button class="text-btn" data-action="delete-workout" data-id="'+w.id+'" aria-label="Видалити активність">×</button></span></div>').join(''):'<div class="empty">Прогулянка, зал, танці або домашній рух.<br>Додай свою активність.</div>')+'</section><section class="panel"><h2>Не лише тренування.</h2><p class="section-sub">Відзначай будь-який рух, який обираєш для себе.</p><button class="habit '+(l.habits.move?'checked':'')+'" data-action="habit" data-id="move"><span class="check-box">'+(l.habits.move?'✓':'')+'</span><span><strong>Сьогодні був мій рух</strong><small>Прогулянка теж рахується</small></span></button></section></div>';}
function profileView(){return pageTop('Тут усе по-твоєму.','МІЙ ПРОСТІР / НАЛАШТУВАННЯ','<button class="btn blue small-btn" data-action="onboard">'+(state.demo?'Почати свою ціль':'＋ Нова ціль')+'</button>')+'<button class="daily-context" data-action="plan"><span>≈</span><span><strong>Мій план калорій і БЖВ</strong><small>Розрахувати за параметрами й активністю</small></span><b>↗</b></button><button class="daily-context" data-action="body-settings"><span>✦</span><span><strong>Мій контекст і помічник</strong><small>Активність, параметри, БЖВ і підказки</small></span><b>↗</b></button><div class="profile-grid"><section class="panel"><div class="panel-head"><h2>Мій профіль</h2><span class="avatar">'+esc(state.profile.name.slice(0,1).toUpperCase())+'</span></div><form id="profileForm"><label class="form-label">Як до тебе звертатися?<input name="name" value="'+esc(state.profile.name)+'" maxlength="40" required></label><div class="form-pair"><label class="form-label">Мій орієнтир, ккал<input name="calories" type="number" min="1" max="10000" step="1" value="'+(state.settings.calories||'')+'" placeholder="Необов’язково"></label><label class="form-label">Орієнтир кроків<input name="steps" type="number" min="1" max="100000" step="1" value="'+(state.settings.steps||'')+'" placeholder="Необов’язково"></label></div><label class="form-label">Фокус харчування<select name="style"><option value="balanced" '+(state.settings.style==='balanced'?'selected':'')+'>Звичайний щоденник</option><option value="flexible" '+(state.settings.style==='flexible'?'selected':'')+'>Гнучкий режим</option><option value="keto" '+(state.settings.style==='keto'?'selected':'')+'>Акцент на вуглеводах / кето</option></select><small>Змінює фокус інтерфейсу. Не призначає раціон.</small></label><button class="btn blue full" type="submit">Зберегти налаштування</button></form><div class="setting-row"><span><strong>Анімація маленької перемоги</strong><small>Святкувати відзначений день</small></span><button class="toggle '+(state.settings.motion?'on':'')+'" data-action="toggle-motion" aria-label="Анімація" aria-pressed="'+state.settings.motion+'"><i></i></button></div><div class="setting-row"><span><strong>Таймер паузи між їжею</strong><small>Необов’язковий режим, без нав’язаного розкладу</small></span><button class="toggle '+(state.settings.fasting?'on':'')+'" data-action="toggle-fasting" aria-label="Таймер паузи" aria-pressed="'+state.settings.fasting+'"><i></i></button></div></section><div><section class="panel"><div class="panel-head"><h2>Мої пристрої</h2><span class="demo-tag">МАКЕТ</span></div>'+['Apple Health','Health Connect'].map((n,i)=>'<div class="integration-row"><span class="integration-logo">'+(i?'◈':'♥')+'</span><span><strong>'+n+'</strong><small>Не підключено</small></span><button class="text-btn" data-action="integration">Деталі ↗</button></div>').join('')+'<p class="small muted">У прототипі кроки, тренування й сон вносяться вручну. Доступ до пристроїв не запитується.</p></section><section class="panel bottom-space"><h2>Мої дані</h2><p class="section-sub">Зберігаються на цьому пристрої в браузері. Без хмарної синхронізації.</p><div class="pill-row"><button class="btn ghost small-btn" data-action="backup">Завантажити копію</button><button class="btn ghost small-btn" data-action="restore">Відновити</button><input id="restoreFile" type="file" accept="application/json" hidden></div><p class="small muted">'+(storageOK?'Локальне збереження працює.':'Браузер не дозволив збереження. Завантаж копію.')+'</p></section><section class="panel bottom-space" style="background:var(--lime)"><div class="tiny-cap">DAYMARK PLUS / КОНЦЕПЦІЯ</div><h2 style="margin:13px 0">Більше простору<br>для твоїх цілей.</h2><button class="btn" data-action="plus">Переглянути концепт ↗</button></section><button class="text-btn" style="margin-top:20px" data-action="demo-reset">Повернути демонстраційні дані</button></div></div>';}
function render(){document.body.classList.toggle('night-theme',currentView==='sleep');document.body.classList.toggle('recipes-view',currentView==='recipes');$('sideNav').innerHTML=navHTML();$('bottomNav').innerHTML=appNav();$('sidebarName').textContent=state.profile.name;$('avatar').textContent=state.profile.name.slice(0,1).toUpperCase();$('demoBanner').classList.toggle('hidden',!state.demo);$('breadcrumb').innerHTML=esc(VIEW_NAMES[currentView])+' <span>/</span> '+(state.demo?'Демонстрація':'Особистий простір');const v={recipes:recipesView,today:todayView,goals:goalsView,journey:journeyView,food:foodView,move:sportView,coach:coachView,supports:supportsView,sleep:sleepView,profile:profileView};$('view').innerHTML=(v[currentView]||todayView)();$('view').classList.toggle('app-home',currentView==='today');if(currentView==='profile')$('restoreFile').onchange=restoreBackup;if(currentView==='recipes')bindRecipes();coachNotifications();}
function navigate(v){if(!VIEW_NAMES[v])return;currentView=v;render();$('view').scrollTop=0;window.scrollTo({top:0,behavior:'instant'});}
function openModal(eyebrow,html){$('modalEyebrow').textContent=eyebrow;$('modalBody').innerHTML=html;if(!$('modal').open)$('modal').showModal();}
function closeModal(){if(modalData.uploadBusy){toast('Фото ще готується');return;}$('modal').close();modalData={};}
$('closeModal').onclick=closeModal;$('modal').addEventListener('cancel',e=>{if(modalData.uploadBusy)e.preventDefault();});
function celebrate(label){if(!state.settings.motion||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const box=$('celebration');box.innerHTML='<div class="celebrate-message">'+esc(label)+'<span style="display:block;font-size:12px;font-weight:400;letter-spacing:0;margin-top:4px">Ще один день для себе.</span></div>'+Array.from({length:30},(_,i)=>'<i class="confetti" style="left:'+ (25+Math.random()*50)+'%;background:'+['#d9fa72','#254df5','#b5a7f6','#ffb59c'][i%4]+';--x:'+(-260+Math.random()*520)+'px;--y:'+(100+Math.random()*470)+'px;--r:'+(-360+Math.random()*720)+'deg;animation-delay:'+Math.random()*.1+'s"></i>').join('');setTimeout(()=>box.replaceChildren(),1500);}
function markModal(minimum=false,d=selectedDate){const g=goal();if(d<g.start||d>g.end||d>today()){toast('Цей день поза періодом твоєї цілі');return;}modalData={date:d,minimum};const existing=g.checks[d];openModal('ТВОЯ ПОЗНАЧКА / '+fdate(d,true),'<h2 class="modal-title">'+(existing?'Цей день уже твій.':minimum?'Маленький крок.<br>Велике значення.':'Цей день —<br>у твою користь.')+'</h2><p class="modal-sub">'+(minimum?esc(g.minimum):'Ти вирішуєш, що сьогодні було твоїм кроком. Необов’язково виконати все.')+'</p><div class="modal-card"><label><input type="radio" name="markType" value="full" '+(!minimum?'checked':'')+'> Мій день для себе</label></div><div class="modal-card"><label><input type="radio" name="markType" value="minimum" '+(minimum?'checked':'')+'> Виконано мій мінімум</label></div><button class="btn blue full" style="margin-top:15px" data-action="confirm-mark">'+(existing?'Оновити позначку':'Закреслити день ↗')+'</button>'+(existing?'<button class="text-btn full" style="margin-top:15px" data-action="unmark">Прибрати позначку</button>':''));}
function startOnboarding(newOnly=false){onboard={step:0,newOnly:newOnly||!state.demo,name:state.demo?'':state.profile.name,kind:'lose',title:'Почуватися краще щодня',start:today(),end:months(today(),4),minimum:'10 хвилин руху й один запис їжі',habits:['food','move','sleep'],age:'',height:'',weight:'',targetWeight:'',calories:'',activityLevel:state.profile.activityLevel||'unknown'};onboardView();}
function onboardView(){return onboardSmartView();}

function collectOnboard(){const form=$('onboardForm'),data=new FormData(form);for(const[k,v]of data)if(k!=='habit')onboard[k]=v;if(onboard.step===2)onboard.habits=data.getAll('habit');}
function searchModal(q=''){return catalogueSearch(q);}

function renderSearch(q){return renderCatalogResults(q);}

function mealModal(mode='manual',product=null,existing=null){const m=existing||{id:uid(),name:product?.name||'',type:product?.unit==='ml'?'drink':'snack',grams:product?.serving||100,kcal:null,p:null,f:null,c:null,source:mode==='label'?'label':product?'reference':'manual',emoji:product?.emoji||'◌'};modalData={mode:'meal',meal:structuredClone(m),product,per100:!!product||mode==='label'};openModal(mode==='label'?'ЗА ЕТИКЕТКОЮ / РОЗРАХУНОК':'МІЙ ЩОДЕННИК / ЗАПИС','<h2 class="modal-title">'+(existing?'Твій запис.':'Додай у свій день.')+'</h2>'+(product?productNotice(product):existing?.foodRef?productNotice(existing.foodRef):'')+'<form id="mealForm"><label class="form-label">Назва<input name="name" value="'+esc(m.name)+'" maxlength="140" placeholder="Що ти з’їв / з’їла?" required></label><div class="form-pair"><label class="form-label">Прийом їжі<select name="type">'+Object.entries(TYPE_NAMES).map(([k,n])=>'<option value="'+k+'" '+(m.type===k?'selected':'')+'>'+n+'</option>').join('')+'</select></label><label class="form-label">Порція, '+((product?.unit||m.unit)==='ml'?'мл':'г')+'<input id="portionGrams" type="number" name="grams" value="'+m.grams+'" min=".1" max="10000" step="any" required></label></div><div class="soft-check"><input type="checkbox" id="per100" '+(modalData.per100?'checked':'')+'><label for="per100">Значення нижче — на 100 г / мл</label></div><div class="form-pair"><label class="form-label">Калорії<input id="foodKcal" type="number" name="kcal" min="0" max="50000" step="any" value="'+(product?foodInputValue(product.kcal):m.kcal??'')+'" placeholder="Не вказано"></label><label class="form-label">Білки, г<input type="number" name="p" min="0" max="10000" step="any" value="'+(product?foodInputValue(product.p):m.p??'')+'"></label></div><div class="form-pair"><label class="form-label">Жири, г<input type="number" name="f" min="0" max="10000" step="any" value="'+(product?foodInputValue(product.f):m.f??'')+'"></label><label class="form-label">Вуглеводи, г<input type="number" name="c" min="0" max="10000" step="any" value="'+(product?foodInputValue(product.c):m.c??'')+'"></label></div><div class="modal-card"><span class="small muted">У моїй порції</span><div id="portionResult" style="font-size:32px;font-weight:750;letter-spacing:-1px">—</div></div><label class="soft-check"><input type="checkbox" name="favorite">Зберегти як звичну страву</label><button class="btn blue full" type="submit">Зберегти запис ↗</button>'+(existing?'<button class="text-btn full" style="margin-top:15px" type="button" data-action="delete-meal" data-id="'+m.id+'">Видалити запис</button>':'')+'</form>');$('mealForm').oninput=portionResult;portionResult();}
function portionResult(){const form=$('mealForm');if(!form)return;const data=new FormData(form),k=data.get('kcal'),g=Number(data.get('grams')),factor=$('per100').checked?g/100:1;$('portionResult').textContent=k===''?'Без оцінки':num(foodFormNumber('kcal',k)*factor)+' ккал';}
function photoModal(){modalData={mode:'photo',photo:null};openModal('AI ФОТО / МАКЕТ СЦЕНАРІЮ','<h2 class="modal-title">Сфоткай.<br>Запам’ятай свій смак.</h2><p class="modal-sub">Завантаж фото для запису або подивись, як виглядатиме оцінка. Розпізнавання у прототипі не підключене.</p><label class="photo-zone">'+icon('camera')+'<strong>Їжа, кава чи етикетка</strong><small>З камери чи галереї · зберігається локально</small><input id="plateFile" type="file" accept="image/*" hidden></label><div id="photoFeedback"></div><button class="btn blue full" style="margin-top:17px" data-action="ai-demo">Подивитися приклад AI-оцінки ↗</button><p class="field-help">Приклад не аналізує завантажене фото. Реальна AI-оцінка потребує окремого сервісу.</p>');$('plateFile').onchange=uploadPlate;}
async function uploadPlate(e){const f=e.target.files[0];if(!f)return;if(!f.type.startsWith('image/')||f.size>25*1024*1024){toast('Обери фото до 25 МБ');return;}modalData.uploadBusy=true;try{const source=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(f);});const im=await new Promise((res,rej)=>{const i=new Image();i.onload=()=>res(i);i.onerror=rej;i.src=source;});const c=document.createElement('canvas'),scale=Math.min(1,900/Math.max(im.width,im.height));c.width=Math.round(im.width*scale);c.height=Math.round(im.height*scale);c.getContext('2d').drawImage(im,0,0,c.width,c.height);modalData.photo=c.toDataURL('image/jpeg',.75);$('photoFeedback').innerHTML='<img class="upload-preview" src="'+modalData.photo+'" alt="Твоє завантажене фото"><p class="note">Фото готове до запису. Аналіз не підключений — калорії можна внести вручну.</p><button class="btn ghost full" data-action="photo-manual">Додати це фото до запису</button>';}catch{toast('Не вдалося відкрити фото. Спробуй JPG або PNG.');}finally{modalData.uploadBusy=false;}}
function bowlArt(){return '<svg viewBox="0 0 240 200" aria-label="Ілюстрація демонстраційного боулу"><ellipse cx="120" cy="107" rx="90" ry="77" fill="#a5b58c" opacity=".25"/><ellipse cx="120" cy="97" rx="87" ry="73" fill="#fffdf8"/><ellipse cx="120" cy="96" rx="73" ry="61" fill="#edf1df"/><path d="M52 91c10-50 61-61 70-47l-8 52-53 31Z" fill="#bdcb73"/><g fill="#749a42"><ellipse cx="67" cy="77" rx="11" ry="17" transform="rotate(-30 67 77)"/><ellipse cx="90" cy="58" rx="14" ry="10"/><ellipse cx="84" cy="98" rx="18" ry="11" transform="rotate(-30 84 98)"/></g><path d="M122 44c30 0 59 25 61 44l-51 19-22-10Z" fill="#e1c186"/><g stroke="#cba86c" stroke-width="2"><path d="m135 55 23 9m-32 4 36 12m-42 1 32 12"/></g><g fill="#e9ab79" stroke="#cf895a" stroke-width="1"><rect x="100" y="106" width="45" height="17" rx="5" transform="rotate(-20 100 106)"/><rect x="110" y="127" width="43" height="17" rx="5" transform="rotate(-20 110 127)"/><rect x="155" y="96" width="25" height="16" rx="5" transform="rotate(-20 155 96)"/></g><g fill="#d86b51"><circle cx="73" cy="123" r="11"/><circle cx="92" cy="138" r="10"/><circle cx="64" cy="109" r="8"/></g><path d="m135 37 16 7m-9 92 18-8" stroke="#648443" stroke-width="2" stroke-linecap="round"/></svg>';}
function aiDemo(){modalData={mode:'ai',items:[{name:'Куряче філе',grams:120,kcal100:165,p:31,f:3.6,c:0},{name:'Готовий рис',grams:150,kcal100:130,p:2.7,f:.3,c:28},{name:'Овочі',grams:100,kcal100:25,p:1.2,f:.3,c:4.5},{name:'Олія / заправка',grams:10,kcal100:884,p:0,f:100,c:0}]};openModal('DEMO / ЯК ПРАЦЮВАТИМЕ AI','<div class="demo-tag">ФІКСОВАНИЙ ПРИКЛАД · НЕ АНАЛІЗ ФОТО</div><h2 class="modal-title">Боул із куркою.</h2><div class="scan-demo">'+bowlArt()+'<div class="scan-cross"></div><span class="scan-label one" id="scanChicken">Курка · 120 г</span><span class="scan-label two" id="scanRice">Рис · 150 г</span></div><div class="eyebrow">ОРІЄНТОВНА ЕНЕРГІЯ ПОРЦІЇ</div><div class="estimate-range" id="aiRange"></div><p class="small muted">Залежить від ваги й заправки. Це демонстраційний діапазон, не гарантована похибка.</p><div id="aiItems">'+modalData.items.map((x,i)=>'<div class="estimate-row"><span>'+x.name+'</span><label><input type="number" min="0" max="3000" step="any" data-ai-index="'+i+'" value="'+x.grams+'" aria-label="'+x.name+', грами"></label><span id="aiKcal'+i+'"></span></div>').join('')+'</div><p class="note">Олія, соус і вага готової порції часто потребують уточнення. Зміни грами й подивись на перерахунок.</p><button class="btn blue full" data-action="save-ai-demo">Додати демо-приклад у щоденник</button>');$('aiItems').oninput=e=>{const i=e.target.dataset.aiIndex;if(i!==undefined&&e.target.validity.valid){modalData.items[Number(i)].grams=Number(e.target.value);aiResult();}};aiResult();}
function aiTotals(){return modalData.items.reduce((a,x)=>{a.kcal+=x.kcal100*x.grams/100;for(const k of ['p','f','c'])a[k]+=x[k]*x.grams/100;return a;},{kcal:0,p:0,f:0,c:0});}
function aiResult(){$('scanChicken').textContent='Курка · '+num(modalData.items[0].grams)+' г';$('scanRice').textContent='Рис · '+num(modalData.items[1].grams)+' г';const t=aiTotals();$('aiRange').innerHTML=num(t.kcal*.8)+'–'+num(t.kcal*1.2)+' <small>ккал</small>';modalData.items.forEach((x,i)=>$('aiKcal'+i).textContent=num(x.kcal100*x.grams/100)+' ккал');}
function foodAddModal(){openModal('ХАРЧУВАННЯ / МІЙ ЗАПИС','<h2 class="modal-title">Як тобі зручніше?</h2><p class="modal-sub">Повний вибір: від кави на ходу до зваженої порції.</p><div class="choice-grid">'+[['photo','camera','За фото','Завантажити / сценарій AI'],['search','search','Пошук продукту','Продукти, кафе й ресторани'],['label','barcode','За етикеткою','Грами та значення на 100 г'],['manual','plus','Швидкий запис','Назва й калорії порції']].map(([a,i,n,sub])=>'<button class="choice" data-action="'+a+'">'+icon(i)+'<b>'+n+'</b><span>'+sub+'</span></button>').join('')+'</div>'+(state.favorites.length?'<h3>Мої звичні страви</h3>'+state.favorites.map(f=>'<button class="search-item" data-action="favorite-use" data-id="'+f.id+'"><span><b>'+esc(f.name)+'</b><small>'+num(f.kcal)+' ккал · '+num(f.grams)+' г / мл</small></span><span>＋</span></button>').join(''):''));}
function shareModal(){const g=goal(),n=completed(g);openModal('STORY CARD / ТВОЯ ІСТОРІЯ','<h2 class="modal-title">Шляхом хочеться<br>ділитися.</h2><div class="share-preview"><div class="wordmark">daymark.</div><h2>'+esc(g.title)+'.</h2><span class="share-number">'+n+'</span><div class="share-days">днів для себе. Я продовжую.</div><div class="mini-checks">'+Array.from({length:Math.min(7,n)},()=>'<i></i>').join('')+'</div><div class="share-bottom"><span>'+fdate(g.start)+' → '+fdate(g.end)+'</span><span>Мій темп. Моя ціль.</span></div></div><p class="small muted">Картка не містить ваги, калорій або фотографій тіла. '+(state.demo?'На ній демонстраційний прогрес.':'')+'</p><button class="btn blue full" data-action="download-story">Завантажити для Stories · PNG</button>');}
function drawWrapped(ctx,text,x,y,maxWidth,lineHeight,maxLines=3){const words=text.split(' ');let line='',lines=0;for(const w of words){const candidate=line?line+' '+w:w;if(ctx.measureText(candidate).width>maxWidth&&line){ctx.fillText(line,x,y);line=w;y+=lineHeight;lines++;if(lines>=maxLines-1){line=words.slice(words.indexOf(w)).join(' ');break;}}else line=candidate;}ctx.fillText(line.slice(0,75),x,y);return y;}
function downloadStory(){const g=goal(),n=completed(g),c=document.createElement('canvas');c.width=1080;c.height=1920;const ctx=c.getContext('2d');ctx.fillStyle='#254df5';ctx.fillRect(0,0,1080,1920);ctx.fillStyle='#fff';ctx.font='bold 66px Arial';ctx.fillText('daymark.',90,160);ctx.font='bold 98px Arial';drawWrapped(ctx,g.title+'.',90,430,900,114,4);ctx.font='bold 440px Arial';ctx.fillText(String(n),70,1170);const width=ctx.measureText(String(n)).width;ctx.strokeStyle='#d9fa72';ctx.lineWidth=25;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(90,1090);ctx.lineTo(Math.min(970,90+width),910);ctx.stroke();ctx.fillStyle='#d8e1ff';ctx.font='40px Arial';ctx.fillText('днів для себе. Я продовжую.',90,1300);for(let i=0;i<Math.min(n,7);i++){ctx.fillStyle='#d9fa72';ctx.beginPath();ctx.roundRect(90+i*108,1390,86,86,16);ctx.fill();ctx.strokeStyle='#171a1c';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(106+i*108,1444);ctx.lineTo(159+i*108,1416);ctx.stroke();}ctx.fillStyle='#fff';ctx.font='30px Arial';ctx.fillText(fdate(g.start)+' → '+fdate(g.end),90,1690);ctx.fillText('Мій темп. Моя ціль.',90,1745);if(state.demo){ctx.font='24px Arial';ctx.fillStyle='#d8e1ff';ctx.fillText('DAYMARK / ДЕМО-КОНЦЕПТ',90,1830);}c.toBlob(blob=>{if(blob)download(blob,'daymark-my-path.png');else toast('Не вдалося створити зображення');},'image/png');}
function spacesModal(){const l=log(),t=totals();openModal('МОЇ ПРОСТОРИ / ГОРТАЙ','<h2 class="modal-title">Один ти.<br>Різні сторони життя.</h2><p class="modal-sub">Гортай картки, як екрани застосунків. Обери простір, у який хочеш перейти.</p><div class="space-switcher">'+[['supports','#e4f2c9','#536436','Мої опори','Мій набір','Маленькі дії під мою ціль.'],['recipes','#ffe1cf','#171a1c','Ідеї їжі','100 ідей','Що приготувати сьогодні?'],['today','var(--blue)','#fff','Мій день','Твоя ціль','Позначка за позначкою.'],['food','#ffc6ad','#171a1c','Їжа',num(t.kcal)+' ккал','Внесено у щоденник.'],['move','var(--lime)','#171a1c','Рух',num(l.steps),'Кроків у своєму темпі.'],['sleep','#171a3b','#dedaff','Сон',sleepDuration(l.sleep)?num(sleepDuration(l.sleep),1)+' г':'☾','Час на відновлення.']].map(([v,b,c,n,value,sub])=>'<button class="switch-card" style="background:'+b+';color:'+c+'" data-view="'+v+'"><span class="tiny-cap">ПРОСТІР / '+n+'</span><h2>'+n+'.</h2><div><b style="font-size:'+(v==='today'?'40':'52')+'px">'+value+'</b><p>'+sub+'</p></div><span>Відкрити простір ↗</span></button>').join('')+'</div>');}
function integrationModal(){openModal('ПРИСТРОЇ / НАСТУПНИЙ ЕТАП','<h2 class="modal-title">Твій ритм.<br>З твоїх пристроїв.</h2><p class="modal-sub">Макет підключення для майбутнього iOS та Android застосунку. Зараз підключення не виконується.</p>'+[['♥','Apple Health','Кроки, тренування, сон з iPhone та Apple Watch'],['◈','Health Connect','Дані сумісних Android-застосунків і пристроїв']].map(([i,n,s])=>'<div class="integration-row"><span class="integration-logo">'+i+'</span><span><strong>'+n+'</strong><small>'+s+'</small></span></div>').join('')+'<div class="modal-card"><h3>Ти керуєш доступом</h3><p class="small muted">У готовому застосунку — окремий дозвіл на кожен тип даних, джерело запису та можливість відключити синхронізацію.</p></div><p class="note">У майбутньому зчитуватимемо активні ккал, кроки, тренування й сон лише з дозволу користувача. Денний підсумок уже міститиме тренування — повторного додавання не буде.</p><button class="btn blue full" data-action="watch-day">Поки внести показники вручну ↗</button>');}
function plusModal(){openModal('DAYMARK PLUS / ЦІНОВА ГІПОТЕЗА','<h2 class="modal-title">Більше можливостей.<br>Та сама твоя ціль.</h2><div class="plus-price">$1.99<small> / місяць</small></div><p class="small muted">Попередня ідея ціни. У прототипі немає оформлення чи списання коштів.</p><ul class="plus-features"><li>Декілька цілей і власні календарі</li><li>Розширені підсумки й оформлення Stories</li><li>Збережені страви й швидке повторення</li><li>AI-оцінка — ліміт і вартість ще перевіряються</li></ul><div class="note">Базова ідея: календар і ручний щоденник залишаються доступними. Усі екрани макета можна переглядати без підписки.</div><button class="btn blue full" style="margin-top:20px" data-action="close">Продовжити тестувати ↗</button>');}
function sleepLogModal(){const l=log(),s=l.sleep||{bed:'23:00',wake:'07:00',quality:'okay'};openModal('СОН / ЗАПИС ВРУЧНУ','<h2 class="modal-title">Як минула<br>твоя ніч?</h2><form id="sleepForm"><div class="form-pair"><label class="form-label">Коли ліг / лягла<input type="time" name="bed" value="'+s.bed+'" required></label><label class="form-label">Коли прокинувся / прокинулася<input type="time" name="wake" value="'+s.wake+'" required></label></div><label class="form-label">Моє відчуття<select name="quality">'+[['good','Відновився / відновилася'],['okay','Звичайно'],['tired','Хочеться ще відпочити']].map(([k,n])=>'<option value="'+k+'" '+(s.quality===k?'selected':'')+'>'+n+'</option>').join('')+'</select></label><p class="note">Запис для '+fdate(selectedDate,true)+'. Враховуємо перехід через північ. Фази сну без пристрою не визначаємо.</p><p id="formError" class="form-error"></p><button class="btn blue full" type="submit">Зберегти сон ↗</button></form>');}
function stepsModal(){openModal('РУХ / КРОКИ','<h2 class="modal-title">Кожен крок<br>у твою історію.</h2><form id="stepsForm"><label class="form-label">Кроків за '+fdate(selectedDate)+'<input name="steps" type="number" min="0" max="200000" step="1" value="'+log().steps+'" required></label><p class="note">Внесення вручну. Підключення пристроїв у макеті не працює.</p><button class="btn blue full" type="submit">Зберегти</button></form>');}
function legacyWorkoutModal(){openModal('РУХ / МОЯ АКТИВНІСТЬ','<h2 class="modal-title">Що було<br>твоїм рухом?</h2><form id="workoutForm"><label class="form-label">Активність<input name="name" placeholder="Зал, прогулянка, танці…" maxlength="80" required></label><label class="form-label">Тривалість, хв<input name="minutes" type="number" min="1" max="1440" step="1" required></label><p class="note">Тривалість записуємо. Витрачені калорії без даних не вигадуємо.</p><button class="btn blue full" type="submit">Додати активність ↗</button></form>');}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function validDate(s){return typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&!isNaN(dt(s).getTime())&&key(dt(s))===s;}
function validateState(data){
 if(!data||data.version!==1||!Array.isArray(data.goals)||!data.goals.length||data.goals.length>30||!data.logs||typeof data.logs!=='object'||Array.isArray(data.logs)||!data.profile||typeof data.profile.name!=='string'||!data.profile.name.trim()||!data.settings||!Array.isArray(data.favorites)||data.favorites.length>50)throw Error('Копія не підтримується');
 const str=(v,n)=>typeof v==='string'?v.slice(0,n):'';
 const number=(v,max,nullable=false)=>{if(nullable&&(v===null||v===undefined||v===''))return null;if(typeof v!=='number'||!Number.isFinite(v)||v<0||v>max)throw Error('Некоректне число');return v;};
 const id=v=>{if(typeof v!=='string'||! /^[A-Za-z0-9_-]{1,80}$/.test(v))throw Error('Некоректний ідентифікатор');return v;};
 const meal=m=>{if(!m||!TYPE_NAMES[m.type]||typeof m.name!=='string')throw Error('Некоректна їжа');const x={id:id(m.id),name:str(m.name,140),type:m.type,grams:number(m.grams,10000),kcal:number(m.kcal,5000000,true),p:number(m.p,1000000,true),f:number(m.f,1000000,true),c:number(m.c,1000000,true),source:['manual','label','demo','photo-demo','restaurant','reference','calculated','user-food'].includes(m.source)?m.source:'manual',emoji:str(m.emoji,8)||'◌'};x.unit=m.unit==='ml'?'ml':'g';if(m.foodRef&&typeof m.foodRef==='object'){const z=m.foodRef;x.foodRef={id:str(z.id,100),brand:str(z.brand,100),url:safeSourceURL(z.url),quality:str(z.quality,30),checked:validDate(z.checked)?z.checked:'',originalName:str(z.originalName,1000),unit:z.unit==='ml'?'ml':'g',serving:number(z.serving,10000,true),review:str(z.review,300)};}if(m.photo){if(typeof m.photo!=='string'||m.photo.length>4000000||!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(m.photo))throw Error('Некоректне фото');x.photo=m.photo;}return x;};
 const out={version:1,demo:!!data.demo,profile:{name:str(data.profile.name,40),age:str(String(data.profile.age||''),3),height:str(String(data.profile.height||''),5),weight:str(String(data.profile.weight||''),6),targetWeight:str(String(data.profile.targetWeight||''),6),activityLevel:ACTIVITY_LEVELS[data.profile.activityLevel]?data.profile.activityLevel:'unknown',sex:['male','female'].includes(data.profile.sex)?data.profile.sex:''},settings:{calories:number(data.settings.calories,10000,true),steps:number(data.settings.steps,100000,true),sleep:number(data.settings.sleep,24,true),style:['balanced','flexible','keto'].includes(data.settings.style)?data.settings.style:'balanced',fasting:!!data.settings.fasting,motion:data.settings.motion!==false},goals:[],logs:{},favorites:data.favorites.map(meal),active:'',fastingStart:number(data.fastingStart,Date.now(),true)};
 const ids=new Set();for(const g of data.goals){if(!g||!validDate(g.start)||!validDate(g.end)||diff(g.start,g.end)<0||diff(g.start,g.end)>730||!Array.isArray(g.habits)||!g.habits.length||g.habits.some(h=>!HABITS[h])||!g.checks||typeof g.checks!=='object'||typeof g.title!=='string')throw Error('Некоректна ціль');const gid=id(g.id);if(ids.has(gid))throw Error('Повтор цілі');ids.add(gid);const checks={};for(const[d,v]of Object.entries(g.checks))if(validDate(d)&&d>=g.start&&d<=g.end&&['full','minimum'].includes(v))checks[d]=v;const supportRules=normalizeSupportRules(g.supportRules,g.habits,number,str);out.goals.push({supportRules,id:gid,title:str(g.title,90),kind:GOAL_KINDS[g.kind]?g.kind:'custom',start:g.start,end:g.end,minimum:str(g.minimum,180),habits:[...new Set(g.habits)],checks});}
 out.active=ids.has(data.active)?data.active:out.goals[0].id;
 if(Object.keys(data.logs).length>1000)throw Error('Забагато дат');for(const[d,l]of Object.entries(data.logs)){if(!validDate(d)||!l||!Array.isArray(l.meals)||l.meals.length>100||!Array.isArray(l.workouts)||l.workouts.length>100||!l.habits)throw Error('Некоректний день');const x={habits:Object.fromEntries(Object.keys(HABITS).map(h=>[h,!!l.habits[h]])),water:number(l.water,100),steps:number(l.steps,200000),meals:l.meals.map(meal),workouts:l.workouts.map(w=>normalizeWorkout(w,number,id,str)),sleep:null};if(l.sleep){const time=v=>typeof v==='string'&&/^([01]\d|2[0-3]):[0-5]\d$/.test(v);if(!time(l.sleep.bed)||!time(l.sleep.wake))throw Error('Некоректний сон');x.sleep={bed:l.sleep.bed,wake:l.sleep.wake,quality:['good','okay','tired'].includes(l.sleep.quality)?l.sleep.quality:'okay'};}x.supportValues=normalizeSupportValues(l.supportValues,number);x.nutritionComplete=!!l.nutritionComplete;if(l.dailyActivity)x.dailyActivity={activeKcal:number(l.dailyActivity.activeKcal,50000,true),device:str(l.dailyActivity.device,80),source:'watch-manual'};if(l.checkIn)x.checkIn={hunger:['low','medium','high'].includes(l.checkIn.hunger)?l.checkIn.hunger:'medium',energy:['low','okay','high'].includes(l.checkIn.energy)?l.checkIn.energy:'okay'};out.logs[d]=x;}
 out.customFoods=normalizeCustomFoods(data.customFoods,number,id,str);if(data.nutritionPlan?.snapshot){const plan=nutritionEstimate(data.nutritionPlan.snapshot);out.nutritionPlan=plan.ok?{...plan,applied:validDate(data.nutritionPlan.applied)?data.nutritionPlan.applied:today(),method:'Mifflin-St Jeor + PAL v1'}:null;}out.recipeExtras=normalizeRecipeExtras(data.recipeExtras);out.settings.macros=Object.fromEntries(['p','f','c'].map(k=>[k,number(data.settings.macros?.[k],1000,true)]));out.settings.weeklyMinutes=number(data.settings.weeklyMinutes,10080,true);out.settings.coach=Object.fromEntries(['enabled','nutrition','sleep','move'].map(k=>[k,data.settings.coach?.[k]!==false]));return out;
}
async function restoreBackup(e){const file=e.target.files[0];if(!file)return;try{if(file.size>30*1024*1024)throw Error();const data=validateState(JSON.parse(await file.text()));if(!confirm('Замінити поточний прототип даними з копії?'))return;state=data;persist();render();toast('Копію відновлено');}catch{toast('Не вдалося прочитати копію DAYMARK. Поточні дані збережено.');}e.target.value='';}
const RECIPE_CATEGORIES={breakfast:'Сніданки',lunch:'Обіди',dinner:'Вечері',snack:'Перекуси',dessert:'Десерти'};
const RECIPE_FOCUS={all:'Будь-яка основа',poultry:'Курка та індичка',meat:'Яловичина та свинина',fish:'Риба',seafood:'Морепродукти',dairy:'Сир і молочне',egg:'Омлети та страви з яйцем',veg:'Без м’яса та риби'};
let recipeFilter={category:'all',focus:'all',maxTime:0,collection:'all',query:'',exclude:[],pantry:[]},recipePageSize=18;
function recipeExtras(){return state.recipeExtras||(state.recipeExtras={saved:[],cart:[],checked:[]});}
function normalizeRecipeExtras(value){if(!value||typeof value!=='object')return{saved:[],cart:[],checked:[]};const ids=new Set(RECIPES.map(r=>r.id));return{saved:Array.isArray(value.saved)?[...new Set(value.saved.filter(id=>ids.has(id)))].slice(0,100):[],cart:Array.isArray(value.cart)?value.cart.filter(x=>x&&ids.has(x.id)&&Number.isFinite(x.servings)&&x.servings>=.5&&x.servings<=10).slice(0,100).map(x=>({id:x.id,servings:x.servings})):[],checked:Array.isArray(value.checked)?[...new Set(value.checked.filter(id=>RECIPE_INGREDIENTS[id]))]:[]};}
function recipeEstimate(r,servings=1){const t={kcal:0,p:0,f:0,c:0};for(const x of r.ingredients){const n=RECIPE_NUTRITION[x.id],mass=x.qty*(x.id==='egg'?50:1)*servings;for(const k of Object.keys(t))t[k]+=(n[k]||0)*mass/100;}return t;}
function recipeNutrition(r,servings){const t=recipeEstimate(r,servings);return '<div class="recipe-nutrition"><div><span>≈ '+num(Math.round(t.kcal/10)*10)+'</span><small>ккал · '+num(servings,1)+' порц.</small></div><p>Б '+num(t.p)+' г · Ж '+num(t.f)+' г · В '+num(t.c)+' г</p></div>';}
function recipeArt(r,extra=''){return '<div class="recipe-art '+extra+'" style="background-image:url(assets/dishes/'+r.id+'.png);background-size:cover;background-position:center" role="img" aria-label="Згенерована ілюстрація: '+esc(r.title)+'"></div>';}
function recipeSearchText(r){return[r.title,RECIPE_CATEGORIES[r.category],...r.ingredients.map(x=>RECIPE_INGREDIENTS[x.id].name)].join(' ').toLocaleLowerCase('uk').replace(/[’'ʼ]/g,'');}
function recipeMatches(r,f=recipeFilter){if(f.category==='saved'&&!recipeExtras().saved.includes(r.id))return false;if(f.category!=='all'&&f.category!=='saved'&&r.category!==f.category)return false;if(f.focus==='veg'&&r.ingredients.some(x=>['chicken','turkey','beef','pork','mince','salmon','whitefish','tuna','shrimp'].includes(x.id)))return false;if(f.focus==='egg'&&!r.ingredients.some(x=>x.id==='egg'))return false;if(!['all','veg','egg'].includes(f.focus)&&r.protein!==f.focus)return false;if(f.maxTime&&r.minutes>f.maxTime)return false;if(f.collection==='protein'&&recipeEstimate(r).p<20)return false;if(f.collection==='quick'&&r.minutes>15)return false;if(f.collection==='no-cook'&&!r.noCook)return false;if(f.collection==='budget'&&!r.budget)return false;if(f.collection==='sweet'&&r.category!=='dessert'&&!/сирник|банан|ягод|вівсян|сирна миска|яблук|персик|груш|крем-сирний/.test(r.title.toLocaleLowerCase('uk')))return false;if(f.collection==='home'&&!/борщ|котлет|окрош|вареник|тефтел|греч|пюре|капуст|рагу|суп/.test(r.title.toLocaleLowerCase('uk')))return false;if(f.exclude.some(a=>r.ingredients.some(x=>RECIPE_INGREDIENTS[x.id].allergens.includes(a)||(a==='nuts'&&x.id==='peanut'))))return false;if(f.pantry.some(id=>!r.ingredients.some(x=>x.id===id)))return false;if(f.query.trim()){const terms=f.query.toLocaleLowerCase('uk').replace(/[’'ʼ]/g,'').split(/[\s,]+/).filter(Boolean),text=recipeSearchText(r);const aliases={'курка':'куряч','курица':'куряч','мясо':'ялович','риба':'риб','рыба':'риб','індичка':'індич','яйця':'яйц','завтрак':'снідан','творог':'сир','картошка':'картопл','десерт':'десерт'};if(!terms.every(t=>text.includes(t)||aliases[t]&&text.includes(aliases[t])))return false;}return true;}
function matchedRecipes(){return RECIPES.filter(r=>recipeMatches(r));}
function recipeCard(r){const saved=recipeExtras().saved.includes(r.id);return '<article class="recipe-card"><button class="recipe-open" data-action="recipe-open" data-id="'+r.id+'" aria-label="Відкрити рецепт: '+esc(r.title)+'">'+recipeArt(r)+'<div class="recipe-card-body"><span class="recipe-category">'+RECIPE_CATEGORIES[r.category]+'</span><h3>'+esc(r.title)+'</h3><div class="recipe-kcal"><strong>≈ '+num(Math.round(recipeEstimate(r).kcal/10)*10)+'</strong><span> ккал / порція</span></div><div class="recipe-meta"><span>◷ '+r.minutes+' хв</span><span>'+r.ingredients.length+' інгредієнтів</span>'+(r.noCook?'<span>Без плити</span>':'')+'</div></div></button><button class="recipe-save '+(saved?'saved':'')+'" data-action="recipe-save" data-id="'+r.id+'" aria-label="'+(saved?'Прибрати зі збережених':'Зберегти рецепт')+'" aria-pressed="'+saved+'">'+(saved?'♥':'♡')+'</button></article>';}
function recipeHomeFeature(){return '<section class="recipe-home-feature"><div class="recipe-home-copy"><div class="eyebrow">НОВИЙ ПРОСТІР / 100 ІДЕЙ ДЛЯ ЇЖІ</div><h2>«А що сьогодні<br>приготувати?»</h2><p>Домашня їжа, швидкі сніданки та щось солодке. Відкрий варіант під свій настрій.</p><button class="btn" data-view="recipes">Знайти свою страву '+icon('arrow')+'</button></div><div class="recipe-home-visual">'+recipeArt(RECIPES[0],'home-plate plate-one')+recipeArt(RECIPES.find(r=>r.id==='lunch-2'),'home-plate plate-two')+'<span class="recipe-sticker">ЩОСЬ<br>СМАЧНЕНЬКЕ ↗</span></div></section>';}
function recipesView(){const e=recipeExtras();return pageTop('Що приготуємо сьогодні?','100 ІДЕЙ / ВИБИРАЙ ПІД СЕБЕ','<button class="btn ghost" data-action="shopping">'+icon('basket')+' <span>Мої покупки</span><span class="count-badge">'+e.cart.length+'</span></button>')+'<section class="recipes-hero"><div><span class="tiny-cap">ЗВИЧАЙНІ ПРОДУКТИ. НОВІ ПОЄДНАННЯ.</span><h2>Ідеї закінчились?<br><em>Страви — ні.</em></h2><p>Не хочеш рибу? Обери м’ясо. Немає часу? Знайди щось за 10 хвилин. Або довір вибір нам.</p><button class="btn white" data-action="recipe-random">✳ Обрати за мене</button></div>'+recipeArt(RECIPES[0],'hero-food')+'<span class="recipe-hero-number">100<span>варіантів для<br>твого ритму</span></span></section><div class="recipe-categories" role="group" aria-label="Прийом їжі">'+[['all','Усі ідеї'],...Object.entries(RECIPE_CATEGORIES),['saved','♡ Збережені']].map(([id,n])=>'<button class="recipe-tab '+(recipeFilter.category===id?'active':'')+'" data-action="recipe-category" data-id="'+id+'">'+n+(id==='saved'?' <span>'+e.saved.length+'</span>':'')+'</button>').join('')+'</div><div class="recipes-workspace"><details class="recipe-filter-details" '+''+'><summary>⚙ Підібрати під себе <span>Продукти · час · побажання</span></summary><aside class="recipe-filters"><div class="filter-heading"><h3>Твоя страва.<br>Твої побажання.</h3><button class="text-btn" data-action="recipe-reset">Скинути</button></div><label class="form-label">Що хочеться?<select id="recipeFocus">'+Object.entries(RECIPE_FOCUS).map(([id,n])=>'<option value="'+id+'" '+(recipeFilter.focus===id?'selected':'')+'>'+n+'</option>').join('')+'</select></label><label class="form-label">Скільки є часу?<select id="recipeTime">'+[[0,'Будь-який час'],[10,'До 10 хвилин'],[20,'До 20 хвилин'],[30,'До 30 хвилин']].map(([n,t])=>'<option value="'+n+'" '+(recipeFilter.maxTime===n?'selected':'')+'>'+t+'</option>').join('')+'</select></label><div class="filter-divider"></div><h4>Сьогодні без…</h4>'+[['fish','Риби'],['dairy','Молочних продуктів'],['egg','Яєць'],['nuts','Горіхів і арахісу']].map(([id,n])=>'<label class="recipe-checkbox"><input type="checkbox" data-exclude="'+id+'" '+(recipeFilter.exclude.includes(id)?'checked':'')+'>'+n+'</label>').join('')+'<p class="filter-note">За наведеним складом. Для готових продуктів перевіряй етикетку.</p><div class="filter-divider"></div><h4>Уже є вдома</h4><p class="filter-note">Знайдемо страви з усіма обраними продуктами.</p><label class="form-label" style="margin-bottom:8px"><span class="sr-only">Продукт із холодильника</span><select id="pantryPick"><option value="">Додати продукт…</option>'+Object.entries(RECIPE_INGREDIENTS).filter(([id])=>!recipeFilter.pantry.includes(id)).map(([id,x])=>'<option value="'+id+'">'+x.name+'</option>').join('')+'</select></label><div class="pantry-chips" id="pantryChips">'+recipeFilter.pantry.map(id=>'<button data-action="pantry-remove" data-id="'+id+'">'+RECIPE_INGREDIENTS[id].name+' ×</button>').join('')+'</div></aside></details><section class="recipe-results"><label class="recipe-search">'+icon('search')+'<input id="recipeSearch" type="search" value="'+esc(recipeFilter.query)+'" placeholder="Назва або продукти: сир, лаваш, курка…" aria-label="Пошук ідей їжі"></label><div class="recipe-collections">'+[['all','Усі підбірки'],['quick','⚡ До 15 хв'],['protein','Більше білка'],['home','Домашня класика'],['sweet','Хочеться солодкого'],['no-cook','Без плити'],['budget','Прості продукти']].map(([id,n])=>'<button class="pill '+(recipeFilter.collection===id?'active':'')+'" data-action="recipe-collection" data-id="'+id+'">'+n+'</button>').join('')+'</div><div class="recipe-results-head"><p id="recipeCount"></p><button class="text-btn" data-action="recipe-random">Обрати за мене ✳</button></div><div id="recipeGrid" class="recipe-grid"></div><div id="recipeMore"></div><p class="recipe-disclaimer">Колекція ідей для 1 порції. Кожна страва має власну згенеровану ілюстрацію; вигляд і подача можуть відрізнятися. ≈ Калорії розраховано за складом, це орієнтир: бренд, жирність і кількість олії впливають на результат.</p></section></div>';}
function renderRecipeResults(){if(!$('recipeGrid'))return;const list=matchedRecipes();$('recipeCount').textContent='Знайдено ідей: '+list.length;$('recipeGrid').innerHTML=list.length?list.slice(0,recipePageSize).map(recipeCard).join(''):'<div class="recipe-empty"><span>◌</span><h3>Для такого поєднання поки немає ідей.</h3><p>Спробуй прибрати один продукт або розширити час приготування.</p><button class="btn ghost" data-action="recipe-reset">Показати всю колекцію</button></div>';$('recipeMore').innerHTML=list.length>recipePageSize?'<button class="btn ghost full recipe-load" data-action="recipe-more">Ще ідеї · '+(list.length-recipePageSize)+' попереду ↓</button>':'';}
function bindRecipes(){$('recipeSearch').oninput=e=>{recipeFilter.query=e.target.value;recipePageSize=18;renderRecipeResults();};$('recipeFocus').onchange=e=>{recipeFilter.focus=e.target.value;recipePageSize=18;renderRecipeResults();};$('recipeTime').onchange=e=>{recipeFilter.maxTime=Number(e.target.value);recipePageSize=18;renderRecipeResults();};document.querySelectorAll('[data-exclude]').forEach(el=>el.onchange=()=>{const id=el.dataset.exclude;if(el.checked&&!recipeFilter.exclude.includes(id))recipeFilter.exclude.push(id);else recipeFilter.exclude=recipeFilter.exclude.filter(x=>x!==id);recipePageSize=18;renderRecipeResults();});$('pantryPick').onchange=e=>{if(e.target.value&&!recipeFilter.pantry.includes(e.target.value))recipeFilter.pantry.push(e.target.value);recipePageSize=18;render();};renderRecipeResults();}
function quantity(q){return num(q,1);}
function recipeModal(id,servings=1){const r=RECIPES.find(r=>r.id===id);if(!r)return;modalData={mode:'recipe',recipeId:id,servings};openModal('ІДЕЇ ДЛЯ ЇЖІ / '+RECIPE_CATEGORIES[r.category],'<div class="recipe-detail-image">'+recipeArt(r)+'<span class="image-caption">Ілюстрація саме цієї страви</span></div><div class="recipe-detail-title"><span class="recipe-category">'+RECIPE_CATEGORIES[r.category]+' · '+r.minutes+' хв підготовки та приготування</span><h2 class="modal-title">'+esc(r.title)+'</h2></div><div id="recipeNutrition">'+recipeNutrition(r,servings)+'</div><div class="recipe-detail-tools"><label class="form-label">Порцій<select id="recipeServings">'+[.5,1,1.5,2,3,4,6,10].map(n=>'<option value="'+n+'" '+(n===servings?'selected':'')+'>'+num(n,1)+'</option>').join('')+'</select></label><button class="btn ghost small-btn" data-action="recipe-save-detail" data-id="'+r.id+'">'+(recipeExtras().saved.includes(r.id)?'♥ Збережено':'♡ Зберегти')+'</button></div><div class="recipe-ingredient-box"><h3>Що потрібно</h3><p class="filter-note">Вага до приготування. Квасоля й нут — готові, консерви — без рідини.</p><ul id="recipeIngredientList">'+r.ingredients.map(x=>'<li><span>'+RECIPE_INGREDIENTS[x.id].name+'</span><b>'+quantity(x.qty*servings)+' '+RECIPE_INGREDIENTS[x.id].unit+'</b></li>').join('')+'</ul></div><div class="recipe-method"><h3>Готуємо без метушні</h3><ol>'+r.steps.map(s=>'<li>'+esc(s)+'.</li>').join('')+'</ol><p class="filter-note">Час орієнтовний; охолодження й настоювання вказані окремо, якщо потрібні. Сіль, вода та звичні спеції — за смаком.</p></div><div class="recipe-detail-actions"><button class="btn blue full" data-action="recipe-to-shopping" data-id="'+r.id+'">'+icon('basket')+' До списку покупок</button><button class="btn ghost full" data-action="recipe-to-diary" data-id="'+r.id+'">＋ Додати страву до щоденника</button></div><details class="nutrition-source"><summary>Як пораховано ≈ калорії?</summary><p>Сума за вагою інгредієнтів. 1 яйце = 50 г їстівної частини, 1 мл молока / кефіру / соку ≈ 1 г. Базова порція — весь наведений рецепт; вибір порцій змінює весь обсяг. Ккал округлено до 10.</p><p>Довідник: <a href="https://doi.org/10.5281/zenodo.17550133" target="_blank" rel="noopener">Anses. 2025. Ciqual French food composition table.</a> Для сиру — модель етикетки 5% (121 ккал/100 г). Лаваш наближено до піти, сметану — до вершків 12–25%, фарш — до курячого філе; ягоди — до малини. Це приблизні значення: уточни упаковку своїх продуктів.</p></details>');$('recipeServings').onchange=e=>{modalData.servings=Number(e.target.value);$('recipeNutrition').innerHTML=recipeNutrition(r,modalData.servings);$('recipeIngredientList').innerHTML=r.ingredients.map(x=>'<li><span>'+RECIPE_INGREDIENTS[x.id].name+'</span><b>'+quantity(x.qty*modalData.servings)+' '+RECIPE_INGREDIENTS[x.id].unit+'</b></li>').join('');};}
function shoppingIngredients(){const ingredients={};for(const selected of recipeExtras().cart){const r=RECIPES.find(r=>r.id===selected.id);if(!r)continue;for(const x of r.ingredients){if(!ingredients[x.id])ingredients[x.id]={...RECIPE_INGREDIENTS[x.id],id:x.id,qty:0};ingredients[x.id].qty+=x.qty*selected.servings;}}return Object.values(ingredients);}
function shoppingText(){const all=shoppingIngredients();return 'DAYMARK · Мої покупки\n\n'+[...new Set(all.map(x=>x.aisle))].map(a=>a+'\n'+all.filter(x=>x.aisle===a).map(x=>(recipeExtras().checked.includes(x.id)?'✓ ':'□ ')+x.name+' — '+quantity(x.qty)+' '+x.unit).join('\n')).join('\n\n');}
function shoppingModal(){const e=recipeExtras(),all=shoppingIngredients();let html='<h2 class="modal-title">Менше згадувати.<br>Більше смакувати.</h2><p class="modal-sub">Інгредієнти об’єднані для вибраних страв. Відзначай те, що вже є або куплено.</p>';if(!e.cart.length)html+='<div class="empty">Відкрий будь-яку страву й натисни «До списку покупок».</div>';else{html+='<div class="shopping-recipes">'+e.cart.map((x,i)=>{const r=RECIPES.find(r=>r.id===x.id);return'<div><span>'+esc(r.title)+'<small>'+num(x.servings,1)+' порц.</small></span><button class="icon-button" data-action="shopping-remove" data-value="'+i+'" aria-label="Прибрати страву зі списку">×</button></div>';}).join('')+'</div>';for(const a of [...new Set(all.map(x=>x.aisle))])html+='<section class="shopping-group"><h3>'+a+'</h3>'+all.filter(x=>x.aisle===a).map(x=>'<label class="shopping-item '+(e.checked.includes(x.id)?'checked':'')+'"><input type="checkbox" data-shop-id="'+x.id+'" '+(e.checked.includes(x.id)?'checked':'')+'><span>'+x.name+'</span><b>'+quantity(x.qty)+' '+x.unit+'</b></label>').join('')+'</section>';html+='<div class="form-actions"><button class="btn ghost" data-action="shopping-copy">Скопіювати</button><button class="btn blue" data-action="shopping-download">Завантажити список</button></div><button class="text-btn full" style="margin-top:18px" data-action="shopping-clear">Очистити список покупок</button>';}openModal('МІЙ СПИСОК / '+all.length+' ПРОДУКТІВ',html);document.querySelectorAll('[data-shop-id]').forEach(el=>el.onchange=()=>{const checked=recipeExtras().checked,id=el.dataset.shopId;if(el.checked&&!checked.includes(id))checked.push(id);else recipeExtras().checked=checked.filter(x=>x!==id);el.closest('.shopping-item').classList.toggle('checked',el.checked);persist();});}
function toggleRecipeSaved(id){const e=recipeExtras();e.saved=e.saved.includes(id)?e.saved.filter(x=>x!==id):[...e.saved,id];persist();}
function recipeRandom(){const list=matchedRecipes();if(!list.length){toast('З цими фільтрами поки немає страв. Спробуй прибрати одне побажання.');return;}const value=crypto.getRandomValues(new Uint32Array(1))[0];recipeModal(list[value%list.length].id);}

let calendarExpanded=false,justMarkedDate=null,lastVictory=null;
function energyPanel(){const t=totals(),target=state.settings.calories,p=target?Math.min(t.kcal/target,1):0,remaining=target?Math.max(0,target-t.kcal):null;return '<section class="energy-card"><div class="energy-heading"><button class="energy-label" data-view="food">Енергія сьогодні ↗</button><span class="energy-spark" aria-hidden="true">✳</span></div><div class="energy-readout"><div><span class="energy-value">'+num(t.kcal)+'</span><span class="energy-unit">ккал внесено</span></div><div class="energy-target">'+(target?'<b>'+num(remaining)+'</b><span>'+(t.kcal>target?'орієнтир уже досягнуто':'до мого орієнтира')+'</span>':'<b>Свій<br>темп.</b><span>без заданої норми</span>')+'</div></div><div class="energy-gauge"><i style="width:'+(target?Math.max(3,p*100):3)+'%"></i><span class="gauge-marker" style="left:'+Math.min(96,Math.max(3,p*100))+'%"></span></div><div class="energy-gauge-label"><span>Мій щоденник</span><button data-action="calorie-target">'+(target?num(target)+' ккал · змінити':'Додати свій орієнтир')+'</button></div><div class="energy-macros">'+[['Білки','p','violet'],['Жири','f','peach'],['Вуглеводи','c','lime']].map(([n,k,c])=>'<div><i class="'+c+'"></i><span>'+n+'</span><strong>'+num(t[k],1)+'<small> г</small></strong></div>').join('')+'</div>'+(t.missing?'<p class="energy-incomplete">Ще без оцінки: '+t.missing+' записів. Підсумок неповний.</p>':'')+'<div class="energy-tools"><button class="snap-button" data-action="photo"><span class="snap-icon">'+icon('camera')+'</span><span><b>Сфоткай</b><small>Їжу, напій чи етикетку</small></span><i>↗</i></button><button class="manual-button" data-action="food-add" aria-label="Внести їжу вручну"><span>＋</span><b>Внести</b></button></div></section>';}
function victoryCalendar(g,ym,weekOnly=false){const [year,month]=ym.split('-').map(Number),first=year+'-'+String(month).padStart(2,'0')+'-01',n=new Date(Date.UTC(year,month,0)).getUTCDate(),off=(dt(first).getUTCDay()+6)%7;let h='<div class="calendar-mini victory-grid '+(weekOnly?'week-only':'')+'">'+['Пн','Вт','Ср','Чт','Пт','Сб','Нд'].map(x=>'<span class="week-label">'+x+'</span>').join('');let dates=[];if(weekOnly){const monday=offset(selectedDate,-((dt(selectedDate).getUTCDay()+6)%7));dates=Array.from({length:7},(_,i)=>offset(monday,i));}else{for(let i=0;i<off;i++)h+='<span class="day empty"></span>';dates=Array.from({length:n},(_,i)=>year+'-'+String(month).padStart(2,'0')+'-'+String(i+1).padStart(2,'0'));}for(const d of dates){const c=g.checks[d],inRange=d>=g.start&&d<=g.end;h+='<button class="day '+(c?'completed ':'')+(c==='minimum'?'minimum ':'')+(d===today()?'today ':'')+(!inRange||d>today()?'future ':'')+(d===selectedDate?'active-date ':'')+(d===justMarkedDate?'just-won':'')+'" data-action="calendar-day" data-date="'+d+'" '+(!inRange||d>today()?'disabled':'')+' aria-label="'+fdate(d,true)+(c?' — моя маленька перемога':'')+'"><span class="day-number">'+Number(d.slice(-2))+'</span>'+(c?'<svg class="day-strike" viewBox="0 0 64 64" aria-hidden="true"><path d="M9 45 Q29 30 55 19"/><path class="strike-tail" d="m47 47 3-5 3 5-3 5Z"/></svg>':'')+'</button>';}return h+'</div>';}
function rewardCalendar(){const g=goal(),c=g.checks[selectedDate],dayNo=Math.max(0,Math.min(total(g),diff(g.start,selectedDate)+1)),valid=selectedDate>=g.start&&selectedDate<=g.end&&selectedDate<=today();return '<section class="reward-calendar"><div class="reward-header"><div><span class="overline">МІЙ ШЛЯХ</span><h2>Маленькі перемоги.</h2></div><button class="reward-count" data-view="journey"><b>'+completed(g)+'</b><span>позначок ↗</span></button></div><div class="goal-inline"><span>'+esc(g.title)+'</span><button class="text-btn" data-view="goals">↗</button></div><div class="reward-date-row"><span>'+ (calendarExpanded?monthTitle(monthView):'Цей тиждень')+'</span><button data-action="calendar-expand">'+(calendarExpanded?'Згорнути ↑':'Увесь місяць ↓')+'</button></div>'+(calendarExpanded?'<div class="calendar-month-control"><button data-action="month-prev" aria-label="Попередній місяць">‹</button><span>'+monthTitle(monthView)+'</span><button data-action="month-next" aria-label="Наступний місяць">›</button></div>':'')+victoryCalendar(g,monthView,!calendarExpanded)+'<button class="victory-button '+(c?'is-done':'')+'" data-action="quick-mark" '+(!valid?'disabled':'')+'><span class="victory-icon">'+(c?'✦':'✓')+'</span><span><b>'+(c?'Цей день уже твій!':'Закреслити день')+'</b><small>'+(c?'День '+dayNo+' · ще одна маленька перемога':'День '+dayNo+' · відзнач свій крок')+'</small></span><i>'+(c?'↗':'✳')+'</i></button><div class="reward-bottom"><button data-action="'+(c?'mark':'minimum')+'">'+(c?'Змінити або прибрати позначку':'Сьогодні зроблено мій мінімум')+'</button><span>Без обнулення прогресу</span></div></section>';}
function homeApp(){const dateLine=selectedDate===today()?'СЬОГОДНІ':fdate(selectedDate,true).toUpperCase();return '<div class="app-day-heading"><div><span class="overline">'+dateLine+'</span><h1>Привіт, '+esc(state.profile.name)+'. <span>✳</span></h1></div>'+dateControl()+'</div>'+energyPanel()+rewardCalendar()+'<button class="supports-entry" data-view="supports"><span>✳</span><span><b>Мої опори</b><small>Мій набір під мою ціль</small></span><i>↗</i></button>'+coachTeaser()+sportHomeCard()+'<div class="home-quick-heading"><h2>Для твого ритму</h2><button class="text-btn" data-action="spaces">Усі простори ↗</button></div><div class="quick-tools-grid"><button class="quick-tool lavender" data-action="search"><span>'+icon('search')+'</span><b>Що я їм?</b><small>Знайти продукт</small></button><button class="quick-tool lime" data-action="label"><span>'+icon('barcode')+'</span><b>Є етикетка?</b><small>Розрахуй порцію</small></button><button class="quick-tool peach" data-view="recipes"><span>'+icon('recipes')+'</span><b>Що приготувати?</b><small>100 смачних ідей</small></button><button class="quick-tool ink" data-action="share"><span>↗</span><b>Моя перемога</b><small>Картка для Stories</small></button></div>'+rhythmBanner()+spacesDeck()+habitPanel();}
function appNav(){return [['today','Сьогодні'],['journey','Мій шлях'],['photo','Сфоткай'],['recipes','Ідеї їжі'],['food','Щоденник']].map(([v,n])=>v==='photo'?'<button class="nav-item camera-nav" data-action="photo"><span>'+icon('camera')+'</span><b>'+n+'</b></button>':'<button class="nav-item '+(currentView===v||(currentView==='coach'&&v==='journey')?'active':'')+'" data-view="'+v+'">'+icon(v)+'<span>'+n+'</span></button>').join('');}
function calorieTargetModal(){openModal('МІЙ ОРІЄНТИР / ЗА БАЖАННЯМ','<h2 class="modal-title">Твій власний<br>орієнтир.</h2><p class="modal-sub">Можна внести свій орієнтир або розрахувати стартову оцінку за параметрами й активністю.</p><button class="btn ghost full" data-action="plan">✦ Розрахувати для мене</button><form id="targetForm"><label class="form-label">ккал на день<input type="number" name="calories" min="1" max="10000" value="'+(state.settings.calories||'')+'" placeholder="Можна залишити порожнім"></label><button class="btn blue full" type="submit">Зберегти орієнтир</button></form>');}
function showVictory(mode='full'){if(!state.settings.motion||matchMedia('(prefers-reduced-motion: reduce)').matches){toast('День відзначено. Ще один крок для себе!');return;}const box=$('celebration');box.innerHTML='<div class="victory-burst"><div class="burst-star">✦</div><div class="victory-stamp"><span>'+Number(selectedDate.slice(-2))+'</span><svg viewBox="0 0 100 100"><path d="M13 71 Q49 46 88 25"/></svg></div><h2>'+(mode==='minimum'?'Твій крок — є!':'Маленька перемога!')+'</h2><p>Цей день — частинка твого шляху.</p></div>'+Array.from({length:45},(_,i)=>'<i class="confetti" style="left:'+ (20+Math.random()*60)+'%;background:'+['#d9fa72','#8059ff','#ff875e','#fff4a3'][i%4]+';--x:'+(-240+Math.random()*480)+'px;--y:'+(150+Math.random()*650)+'px;--r:'+(-400+Math.random()*800)+'deg;animation-delay:'+Math.random()*.15+'s"></i>').join('');setTimeout(()=>box.replaceChildren(),1800);}
function quickMark(){const g=goal(),d=selectedDate;if(d<g.start||d>g.end||d>today())return;if(g.checks[d]){markModal(false,d);return;}g.checks[d]='full';lastVictory={goalId:g.id,date:d};justMarkedDate=d;persist();render();showVictory('full');setTimeout(()=>{justMarkedDate=null;},2000);}
function undoLastVictory(){if(!lastVictory)return;const g=state.goals.find(g=>g.id===lastVictory.goalId);if(g)delete g.checks[lastVictory.date];lastVictory=null;persist();render();toast('Позначку прибрано. Твій шлях збережено.');}

