document.addEventListener('click',e=>{const view=e.target.closest('[data-view]');if(view){closeModal();navigate(view.dataset.view);return;}const button=e.target.closest('[data-action]');if(button&&!button.disabled){const fn=actions[button.dataset.action];if(fn)fn(button);}});
document.addEventListener('submit',e=>{const form=e.target;if(!['nutritionPlanForm','supportsForm','supportLogForm','customFoodForm','drinkForm','watchDayForm','bodySettingsForm','checkInForm','targetForm','onboardForm','mealForm','profileForm','stepsForm','sleepForm','workoutForm'].includes(form.id))return;e.preventDefault();if(!form.reportValidity())return;const data=new FormData(form),vals=Object.fromEntries(data.entries());
if(form.id==='customFoodForm'){saveCustomFood(vals);}
if(form.id==='drinkForm'){saveDrink(vals);}
if(form.id==='nutritionPlanForm'){applyNutritionPlan(vals);}
if(form.id==='supportsForm'){saveSupports(vals,data);}
if(form.id==='supportLogForm'){const g=goal(),id=modalData.supportId;if(!g.habits.includes(id)||selectedDate<g.start||selectedDate>g.end||selectedDate>today()){$('supportLogError').textContent='Обери день у межах цієї цілі, який уже настав.';return;}log().supportValues=log().supportValues||{};log().supportValues[g.id+'__'+id]=Number(vals.value);persist();closeModal();render();toast('Твій маленький крок збережено');}
if(form.id==='watchDayForm'){log().dailyActivity=vals.activeKcal!==''?{activeKcal:Number(vals.activeKcal),device:vals.device,source:'watch-manual'}:null;log().steps=Number(vals.steps);persist();closeModal();render();toast('Денні показники оновлено без подвійного додавання');}
if(form.id==='checkInForm'){log().checkIn={hunger:vals.hunger,energy:vals.energy};persist();closeModal();render();toast('Твоє відчуття враховано');}
if(form.id==='bodySettingsForm'){state.profile.activityLevel=ACTIVITY_LEVELS[vals.activityLevel]?vals.activityLevel:'unknown';for(const k of ['age','height','weight'])state.profile[k]=vals[k]||'';state.settings.macros=Object.fromEntries(['p','f','c'].map(k=>[k,vals[k]?Number(vals[k]):null]));state.settings.sleep=vals.sleep?Number(vals.sleep):null;state.settings.weeklyMinutes=vals.weeklyMinutes?Number(vals.weeklyMinutes):null;state.settings.coach=Object.fromEntries(['enabled','nutrition','sleep','move'].map(k=>[k,vals['coach_'+k]==='on']));persist();closeModal();render();toast('Мій контекст збережено. Підказки оновлено.');}
if(form.id==='targetForm'){state.settings.calories=vals.calories?Number(vals.calories):null;persist();closeModal();render();toast('Орієнтир оновлено');}if(form.id==='onboardForm'){collectOnboard();if(onboard.step===1){const n=diff(onboard.start,onboard.end);if(!Number.isFinite(n)||n<0||n>730){$('formError').textContent='Обери період від одного дня до двох років.';return;}}if(onboard.step<2){onboard.step++;onboardView();return;}if(!onboard.habits.length){$('formError').textContent='Обери хоча б одну опору для своєї цілі.';return;}const o=onboard,g={id:uid(),title:o.title.trim(),kind:o.kind,start:o.start,end:o.end,minimum:o.minimum.trim(),habits:o.habits,supportRules:Object.fromEntries(o.habits.map(id=>[id,{target:Number(o['habitTarget_'+id])||SUPPORT_DEFINITIONS[id].target,days:['strength'].includes(id)?[1,3,5]:[0,1,2,3,4,5,6],label:SUPPORT_DEFINITIONS[id].name,automatic:!!SUPPORT_DEFINITIONS[id].auto}])),checks:{}};if(!o.newOnly){state={version:1,demo:false,profile:{name:o.name.trim(),age:o.age,height:o.height,weight:o.weight,targetWeight:o.targetWeight,activityLevel:o.activityLevel||'unknown'},settings:{calories:o.calories?Number(o.calories):null,steps:null,sleep:null,style:'balanced',fasting:false,motion:true},goals:[g],active:g.id,logs:{},favorites:[],fastingStart:null};}else{state.goals.push(g);state.active=g.id;state.profile.name=o.name.trim()||state.profile.name;}selectedDate=today();monthView=o.start.slice(0,7);persist();closeModal();navigate('today');toast('Твій шлях створено. Починай у своєму темпі.');if(o.calculate==='on')planModal();}
if(form.id==='mealForm'){if(log().meals.length>=100&&!log().meals.some(m=>m.id===modalData.meal.id)){toast('У цьому дні вже 100 записів');return;}const factor=$('per100').checked?Number(vals.grams)/100:1,meal={...modalData.meal,name:vals.name.trim(),type:vals.type,grams:Number(vals.grams)};for(const k of ['kcal','p','f','c'])meal[k]=vals[k]===''?null:round(foodFormNumber(k,vals[k])*factor);if(modalData.product&&meal.foodRef&&['kcal','p','f','c'].some(k=>String(vals[k])!==String(foodInputValue(modalData.product[k]))&&Number(vals[k])!==modalData.product[k]))meal.foodRef.review='Харчові значення змінено вручну після вибору джерела.';const i=log().meals.findIndex(m=>m.id===meal.id);if(i>=0)log().meals[i]=meal;else log().meals.push(meal);if(vals.favorite==='on'&&state.favorites.length<50){const copy=structuredClone(meal);delete copy.photo;state.favorites.push({...copy,id:uid()});}log().habits.food=true;log().nutritionComplete=false;persist();closeModal();navigate('food');toast('Запис у твоєму щоденнику');}
if(form.id==='profileForm'){state.profile.name=vals.name.trim();state.settings.calories=vals.calories?Number(vals.calories):null;state.settings.steps=vals.steps?Number(vals.steps):null;state.settings.style=vals.style;persist();render();toast('Налаштування збережено');}
if(form.id==='sleepForm'){const s={bed:vals.bed,wake:vals.wake,quality:vals.quality};if(!sleepDuration(s)){$('formError').textContent='Час початку й завершення мають відрізнятися.';return;}log().sleep=s;persist();closeModal();render();toast('Сон додано до твоєї історії');}
if(form.id==='stepsForm'){log().steps=Number(vals.steps);persist();closeModal();render();toast('Кроки збережено');}
if(form.id==='workoutForm'){saveWorkoutForm(vals);}
});
setInterval(()=>{if(state.settings.fasting&&state.fastingStart&&currentView==='food'&&!$('modal').open)render();},60000);
render();
